--- a/tests/test_stock.py
+++ b/tests/test_stock.py
@@ -55,3 +55,47 @@

 if __name__ == "__main__":
     unittest.main()
+
+class TestSoldOut(unittest.TestCase):
+
+    def test_sold_out_only_when_all_sizes_zero(self):
+        # Test data: City 3 with units in S and M (should not be sold out)
+        stock = {
+            "city3": {
+                "name": "City 3",
+                "units": {
+                    "S": 5,
+                    "M": 3
+                }
+            }
+        }
+        # Expected: no sold out products
+        result = sold_out(stock)
+        self.assertEqual(result, [])
+
+        # Test data: City 3 with no units in any size (should be sold out)
+        stock2 = {
+            "city3": {
+                "name": "City 3",
+                "units": {
+                    "S": 0,
+                    "M": 0
+                }
+            }
+        }
+        # Expected: city3 should be sold out
+        result2 = sold_out(stock2)
+        self.assertEqual(result2, ["city3"])
+
+        # Test data: product with units in some sizes, no units in others (should not be sold out)
+        stock3 = {
+            "city4": {
+                "name": "City 4",
+                "units": {
+                    "S": 0,
+                    "M": 5
+                }
+            }
+        }
+        result3 = sold_out(stock3)
+        self.assertEqual(result3, [])

